    #[test]
    fn fault_classification_matches_section_17() {
        assert_eq!(PluginFault::Timeout.code(), "timeout");
        assert!(PluginFault::Timeout.counts_against_circuit());
        // A structured upstream failure is evidence, not a runtime fault.
        let e = PluginFault::PluginError {
            code: "rate_limited".into(),
            message: "429".into(),
            retryable: true,
            retry_after: Some(5),
        };
        assert!(!e.counts_against_circuit());
        assert_eq!(e.code(), "rate_limited");
    }
